package com.healthwise.user.service;
import com.healthwise.exception.ResourceNotFoundException; import com.healthwise.user.dto.UserDtos.*; import com.healthwise.user.entity.User; import com.healthwise.user.repository.UserRepository; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
/** Own-profile operations. */
@Service public class UserService {private final UserRepository repo;private final PasswordEncoder passwords;public UserService(UserRepository r,PasswordEncoder p){repo=r;passwords=p;}private User user(String id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("User not found"));}private Response dto(User u){return new Response(u.getId(),u.getEmail(),u.getFirstName(),u.getLastName(),u.isEnabled(),u.getCreatedAt(),u.getUpdatedAt());}public Response me(String id){return dto(user(id));}public Response update(String id,Update d){User u=user(id);u.setFirstName(d.firstName().trim());u.setLastName(d.lastName().trim());return dto(repo.save(u));}public void password(String id,PasswordUpdate d){User u=user(id);if(!passwords.matches(d.currentPassword(),u.getPassword()))throw new IllegalArgumentException("Current password is incorrect");u.setPassword(passwords.encode(d.newPassword()));repo.save(u);}public void delete(String id){User u=user(id);u.setEnabled(false);repo.save(u);}}
